@Serializable
data class CredentialDesignRecord
    @JvmOverloads
    constructor(
        val id: Uuid,
        val tenantId: String,
        val alias: String? = null,
        val hostingMode: DesignHostingMode,
        val bindings: List<DesignBinding>,
        val credentialTemplateId: Uuid? = null,
        val issuerDesignId: Uuid? = null,
        val displays: List<LocalizedCredentialDisplay>,
        val claims: List<ClaimPresentation> = emptyList(),
        val renderVariantIds: List<Uuid> = emptyList(),
        val derivedRenderHintsId: Uuid? = null,
        val sourceSnapshotIds: List<Uuid> = emptyList(),
        val contentHash: String? = null,
        /** Optional OCA semantic attribute set this design draws from. When present, the OCA-backed
         *  credential-design resolution derives selective-disclosure and mandatory flags from it. */
        val semanticAttributeSetRef: SemanticAttributeSetRef? = null,
        /** Optional attribute-profile this design draws from. When present, credential-design
         *  resolution derives selective-disclosure and mandatory flags from the profile's resolved
         *  effective projection in preference to [semanticAttributeSetRef]. The id and pinned
         *  version are held as primitives so this IDK contract stays free of the EDK profile types. */
        val attributeProfileId: Uuid? = null,
        val attributeProfileVersion: Long? = null,
        val createdAt: Instant,
        val updatedAt: Instant,
        val credentialType: CredentialTypeDescriptor? = null,
        /**
         * Config-level default deferred-issuance policy for credentials built from this design.
         * Lowest-precedence layer of the config < template < offer merge resolved by
         * `com.sphereon.credential.issuance.pipeline.DeferralPolicyResolver`. Null means this
         * design sets no default (falls through entirely to the template/offer levels).
         */
        val deferral: CredentialDesignDeferralPolicy? = null,
    )

