object DeferralPolicyResolver {
    fun resolve(
        config: DeferralPolicyOverride? = null,
        template: DeferralPolicyOverride? = null,
        offer: DeferralPolicyOverride? = null,
    ): DeferralPolicy {
        val combined = combineOverrides(config, template, offer) ?: return DeferralPolicy()
        val defaults = DeferralPolicy()
        return defaults.copy(
            enabled = combined.enabled ?: defaults.enabled,
            pollIntervalSeconds = combined.pollIntervalSeconds ?: defaults.pollIntervalSeconds,
            maxDeferralSeconds = combined.maxDeferralSeconds ?: defaults.maxDeferralSeconds,
            approvalRequired = combined.approvalRequired ?: defaults.approvalRequired,
        )
    }

    /**
     * Folds any number of overrides into a single override, each argument overriding only the
     * fields set by the ones before it (field-level fall-through preserved — this is what lets
     * callers pre-combine, e.g., a template override with an execution-time override, before the
     * result is later combined with a config default at another layer, without losing "this field
     * was never set" information along the way).
     */
    fun combineOverrides(vararg overrides: DeferralPolicyOverride?): DeferralPolicyOverride? =
        overrides.filterNotNull().fold(null as DeferralPolicyOverride?) { lower, higher ->
            if (lower == null) {
                higher
            } else {
                DeferralPolicyOverride(
                    enabled = higher.enabled ?: lower.enabled,
                    pollIntervalSeconds = higher.pollIntervalSeconds ?: lower.pollIntervalSeconds,
                    maxDeferralSeconds = higher.maxDeferralSeconds ?: lower.maxDeferralSeconds,
                    approvalRequired = higher.approvalRequired ?: lower.approvalRequired,
                )
            }
        }
}

