    ): CborItem<out Any?> {
        val jsonPrimitive: JsonPrimitive? = (element as? JsonPrimitive)?.jsonPrimitive
        val jsonArray: JsonArray? = (element as? JsonArray)?.jsonArray
        val jsonObject: JsonObject? = (element as? JsonObject)?.jsonObject
        val isNull: Boolean = element == JsonNull || element === null
        val isString: Boolean = jsonPrimitive?.isString == true

        if (isNull) {
            return CborNull()
        } else if (isString && jsonPrimitive !== null) {
            return CborString(jsonPrimitive.content)
        } else if (jsonArray !== null) {
            return list.fromJson(jsonArray)
        } else if (jsonObject !== null) {
            if (CborItemJson.isCborItemValueJson(jsonObject)) {
                val key =
                    if (CborItemJson.isCborItemJson(jsonObject)) {
                        (jsonObject["key"] as? JsonPrimitive)?.content
                    } else {
                        null
                    }
                val cddlStr = (jsonObject["cddl"] as? JsonPrimitive)?.content

                if (cddlStr === null) {
                    // cddl key found, but wasn't a primitive, returning a null value
                    return CborNull()
                }
                val cddlObject = util.fromFormat(cddlStr)
                val cborObject = newCborItemFromJson(jsonObject[jsonObject.keys.find { it != CDDL_LITERAL && it != KEY_LITERAL }], cddlObject)
                if (key === null) {
                    return cborObject
                }
                return CborMap(mutableMapOf(Pair(CborString(key), cborObject)))
            }
            // number label keys?
            return CborMap(mutableMapOf(* jsonObject.map { Pair(CborString(it.key), newCborItemFromJson(it.value)) }.toTypedArray()))
        } else if (jsonPrimitive !== null) {
            if (cddl == null) {
                return newCborItem(jsonPrimitive)
            }
            return when (cddl) {
                // Needed because we cannot have inheritance with Kotlin to JS, unfortunately. The fromJson would cause clashes if we put it in the interface
                tstr -> tstr.fromJson(jsonPrimitive)

                Null -> CborNull()

                False -> CborSimple.FALSE

                True -> CborSimple.TRUE

                bool -> bool.fromJson(jsonPrimitive)

                bstr -> bstr.fromJson(jsonPrimitive)

                bytes -> bytes.fromJson(jsonPrimitive)

                float -> float.fromJson(jsonPrimitive)

                float16 -> float16.fromJson(jsonPrimitive)

                float32 -> float32.fromJson(jsonPrimitive)

                float64 -> float64.fromJson(jsonPrimitive)

                full_date -> full_date.fromJson(jsonPrimitive)

                int -> int.fromJson(jsonPrimitive)

                nil -> nil.newNil()

                nint -> nint.fromJson(jsonPrimitive)

                tdate -> tdate.fromJson(jsonPrimitive)

                text -> text.fromJson(jsonPrimitive)

                time -> time.fromJson(jsonPrimitive)

                uint -> uint.fromJson(jsonPrimitive)

                undefined -> undefined.newUndefined()

                else -> cddl.newCborItem(jsonPrimitive)
            }
        }
        return newCborItem(element)
    }

    override fun <T : Any> newCborItem(origValue: T?): CborItem<out Any?> {
        // We are not using inheritance for the methods as that would impact JS export.
        // Since this is a sealed class anyway that is not too bad
        var value = origValue
        val jsonElement: JsonElement? =
            when (value) {
                is JsonPrimitive -> value
                is JsonArray -> value
                is JsonObject -> value
                is JsonNull -> value
                else -> null
            }
        if (value == null) {
            return nil.newNil()
        } else if (value == Unit) {
            return undefined.newUndefined()
        }
        return when (this) {
            tstr -> {
                if (jsonElement === null) {
                    tstr.newString(value.toString())
                } else {
                    tstr.fromJson(jsonElement.jsonPrimitive)
                }
            }

            False -> {
                False.newFalse()
            }

            Null -> {
                Null.newNull()
            }

            True -> {
                True.newTrue()
            }

            any -> {
                return when (value) {
                    is JsonPrimitive -> {
                        val prim = value
                        when {
                            prim.isString -> tstr.fromJson(prim)
                            prim.content == "true" || prim.content == "false" -> bool.fromJson(prim)
                            prim.content.contains('.') || prim.content.contains('e') || prim.content.contains('E') -> float64.fromJson(prim)
                            else -> int.fromJson(prim) // Assume integer if not string, boolean, or float
                        }
                    }

                    is cddl_tstr -> {
                        if (jsonElement === null) {
                            tstr.newString(value)
                        } else {
                            tstr.fromJson(jsonElement.jsonPrimitive)
                        }
                    }

                    is cddl_bstr -> {
                        if (jsonElement === null) {
                            bstr.newByteString(value)
                        } else {
                            bstr.fromJson(jsonElement.jsonPrimitive)
                        }
                    }

                    is cddl_tdate -> {
                        if (jsonElement === null) {
                            tdate.newTDate(value)
                        } else {
                            tdate.fromJson(jsonElement.jsonPrimitive)
                        }
                    }

                    is cddl_full_date -> {
                        if (jsonElement === null) {
                            full_date.newFullDate(value)
                        } else {
                            full_date.fromJson(jsonElement.jsonPrimitive)
                        }
                    }

                    is cddl_bool -> {
                        if (jsonElement === null) {
                            bool.newBool(value)
                        } else {
                            bool.fromJson(jsonElement.jsonPrimitive)
                        }
                    }

                    // Use consolidated Number handling for JS/WasmJs compatibility
                    // (on JS, all numeric `is` checks match any Number, making individual checks unreliable)
                    is Number -> {
                        if (jsonElement === null) {
                            value.toCborItem()
                        } else {
                            val d = value.toDouble()
                            if (d != kotlin.math.floor(d) || d.isInfinite() || d.isNaN()) {
                                float64.fromJson(jsonElement.jsonPrimitive)
                            } else {
                                int.fromJson(jsonElement.jsonPrimitive)
                            }
                        }
                    }

                    is cddl_list<*> -> {
                        if (jsonElement === null) {
                            list.newList(
                                value
                                    .map {
                                        if (it is CborItem<*>) {
                                            it
                                        } else {
                                            any.newCborItem(
                                                it,
                                            )
                                        }
                                    }.toMutableList(),
                            )
                        } else {
                            list.fromJson(jsonElement.jsonArray)
                        }
                    }

                    is cddl_map<*, *> -> {
                        if (jsonElement === null) {
                            map.newMap(
                                mutableMapOf(
                                    * value
                                        .map {
                                            Pair(
                                                if (it.key is CborItem<*>) {
                                                    it.key as CborItem<*>
                                                } else {
                                                    any.newCborItem(it.key)
                                                },
                                                if (it.value is CborItem<*>) {
                                                    it.value as CborItem<*>
                                                } else {
                                                    any.newCborItem(it.value)
                                                },
                                            )
                                        }.toTypedArray(),
                                ),
                            )
                        } else {
                            map.fromJson(jsonElement.jsonObject)
                        }
                    }

                    else -> {
                        throw IllegalArgumentException("newCborItem for $value Not implemented yet")
                    }
                }
            }

            bool -> {
                if (jsonElement === null) {
                    bool.newBool(value == true)
                } else {
                    bool.fromJson(jsonElement.jsonPrimitive)
                }
            }

            bstr -> {
                if (jsonElement === null) {
                    bstr.newByteString(value as ByteArray)
                } else {
                    bstr.fromJson(jsonElement.jsonPrimitive)
                }
            }

            bstr_indef_length -> {
                if (jsonElement === null) {
                    bstr_indef_length.newByteString(value as List<cddl_bstr>)
                } else {
                    TODO("indef cddl from json not implemented yet")
                }
            }

            bytes -> {
                if (jsonElement === null) {
                    bytes.newBytes(value as ByteArray)
                } else {
                    bytes.fromJson(jsonElement.jsonPrimitive)
                }
            }

            float -> {
                if (jsonElement === null) {
                    float.newFloat(value as Float)
                } else {
                    float.fromJson(jsonElement.jsonPrimitive)
                }
            }

            float16 -> {
                if (jsonElement === null) {
                    float16.newFloat16(value as Float)
                } else {
                    float16.fromJson(jsonElement.jsonPrimitive)
                }
            }

            float32 -> {
                if (jsonElement === null) {
                    float32.newFloat32(value as Float)
                } else {
                    float32.fromJson(jsonElement.jsonPrimitive)
                }
            }

            float64 -> {
                if (jsonElement === null) {
                    float64.newFloat64(value as Double)
                } else {
                    float64.fromJson(jsonElement.jsonPrimitive)
                }
            }

            full_date -> {
                if (jsonElement === null) {
                    full_date.newFullDate(value as cddl_full_date)
                } else {
                    full_date.fromJson(jsonElement.jsonPrimitive)
                }
            }

            int -> {
                if (jsonElement === null) {
                    int.newInt(value as Int)
                } else {
                    int.fromJson(jsonElement.jsonPrimitive)
                }
            }

            list -> {
                if (jsonElement === null) {
                    if (value is CborArray<*>) {
                        value
                    } else {
                        list.newList(
                            (value as List<*>)
                                .map {
                                    if (it is CborItem<*>) {
                                        it
                                    } else {
                                        any.newCborItem(
                                            it,
                                        )
                                    }
                                }.toMutableList(),
                        )
                    }
                } else {
                    list.fromJson(jsonElement.jsonArray)
                }
            }

            map -> {
                if (jsonElement === null) {
                    if (value is CborMap<*, *>) {
                        value
                    } else {
                        map.newMap(
                            mutableMapOf(
                                * (value as Map<*, *>)
                                    .map {
                                        Pair(
                                            if (it.key is CborItem<*>) {
                                                it.key as CborItem<*>
                                            } else {
                                                any.newCborItem(it.key)
                                            },
                                            if (it.value is CborItem<*>) {
                                                it.value as CborItem<*>
                                            } else {
                                                any.newCborItem(it.value)
                                            },
                                        )
                                    }.toTypedArray(),
                            ),
                        ) // fixme. Needs inspection of keys and values and map type
                    }
                } else {
                    return map.fromJson(jsonElement.jsonObject)
                }
            }

            nil -> {
                nil.newNil()
            }

            nint -> {
                if (jsonElement === null) {
                    nint.newNInt(
                        if (value is Number) {
                            value.toLong()
                        } else {
                            value as Long
                        }
                    )
                } else {
                    nint.fromJson(
                        jsonElement.jsonPrimitive,
                    )
                }
            }

            tdate -> {
                if (jsonElement === null) {
                    tdate.newTDate(value as cddl_tdate)
                } else {
                    tdate.fromJson(jsonElement.jsonPrimitive)
                }
            }

            text -> {
                if (jsonElement === null) {
                    text.newText(value as cddl_text)
                } else {
                    text.fromJson(jsonElement.jsonPrimitive)
                }
            }

            time -> {
                if (jsonElement === null) {
                    time.newTime(value as cddl_time)
                } else {
                    time.fromJson(jsonElement.jsonPrimitive)
                }
            }

            tstr_indef_length -> {
                if (jsonElement !== null) {
                    tstr_indef_length.newStringIndefLength(value as List<cddl_tstr>)
                } else {
                    TODO("tstr indef length from json to cbor not implemented")
                }
            }

            uint -> {
                if (jsonElement === null) {
                    uint.newUint(
                        if (value is Long) {
                            value
                        } else if (value is Number) {
                            value.toLong()
                        } else {
                            value as Long
                        },
                    )
                } else {
                    uint.fromJson(
                        jsonElement.jsonPrimitive,
                    )
                }
            }

            undefined -> {
                undefined.newUndefined()
            }
        }
    }

