                value.entries
                    .map {
                        Pair(
                            CborString(it.key),
                            when (it.value) {
                                is JsonPrimitive -> any.fromJson(it.value)
                                is JsonArray -> list.fromJson(it.value as JsonArray)
                                is JsonObject -> fromJson(it.value as JsonObject)
                                else -> throw IllegalArgumentException("Unknown type encountered")
                            },
                        )
                    }.toMap()
                    .toMutableMap(),
            )
