internal fun TenantDidBootstrapRequest.validatedMaterials(): IdkResult<List<BootstrapMaterial>, IdkError> {
    if (instanceId.isBlank()) return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap requires an instance id"))
    if (!INSTANCE_ID_PATTERN.matches(instanceId)) {
        return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap instance id contains unsupported characters"))
    }
    if (verificationMethods.isEmpty()) return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap requires verification material"))
    if (verificationMethods.map { it.role }.distinct().size != verificationMethods.size) {
        return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap cannot repeat a verification-method role"))
    }
    val unknownRole = verificationMethods.firstOrNull { it.role !in TenantDidVerificationMethodRole.entries }
    if (unknownRole != null) return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap contains an unsupported role"))
    return verificationMethods.map { it.toBootstrapMaterial(instanceId) }.foldResults()
}

internal fun TenantDidBootstrapVerificationMethod.toBootstrapMaterial(instanceId: String): IdkResult<BootstrapMaterial, IdkError> {
    if (publicJwk.keys.any { it !in PUBLIC_JWK_MEMBERS }) {
        return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap JWK contains a non-public or unsupported member"))
    }
    val kty = publicJwk["kty"]?.toString()?.trim('"')
    if (kty !in setOf("EC", "OKP", "RSA")) {
        return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap requires an asymmetric public JWK"))
    }
    // Parse using the canonical IDK model after the closed-member gate. This rejects malformed
    // curve/key-coordinate combinations rather than storing an arbitrary JSON object.
    runCatching { Json.decodeFromJsonElement(com.sphereon.crypto.core.jose.Jwk.serializer(), publicJwk) }
        .getOrElse {
            return Err(IdkError.ILLEGAL_ARGUMENT_ERROR(message = "tenant DID bootstrap contains an invalid public JWK"))
        }
    return Ok(BootstrapMaterial(instanceId, role, publicJwk))
}

private fun List<IdkResult<BootstrapMaterial, IdkError>>.foldResults(): IdkResult<List<BootstrapMaterial>, IdkError> {
    val result = mutableListOf<BootstrapMaterial>()
    forEach { item -> result += item.getOrElse { return Err(it) } }
    return Ok(result.sortedBy { it.role.ordinal })
}

