    val leftPartyId: Uuid,

    /** The "right" party in the relationship (e.g., employer) */
    @SerialName("rightPartyId")
    val rightPartyId: Uuid,

    /** Type of relationship (references relationship_type.type) */
    @SerialName("relationshipType")
    val relationshipType: String,

    /** Status of the relationship */
    @SerialName("status")
    val status: String = RelationshipStatus.ACTIVE,

    /** When the relationship becomes valid */
    @SerialName("validFrom")
    val validFrom: Instant? = null,

    /** When the relationship expires */
    @SerialName("validUntil")
    val validUntil: Instant? = null,

    /** When the relationship was verified */
    @SerialName("verifiedAt")
    val verifiedAt: Instant? = null,

    /** Who verified the relationship (party ID) */
    @SerialName("verifiedById")
    val verifiedById: Uuid? = null,

    // Audit fields
    /** When the record was created */
    @SerialName("createdAt")
    val createdAt: Instant,

    /** Who created the record (party ID) */
    @SerialName("createdById")
    val createdById: Uuid? = null,

    /** When the record was last updated */
    @SerialName("updatedAt")
    val updatedAt: Instant,

    /** Who last updated the record (party ID) */
    @SerialName("updatedById")
    val updatedById: Uuid? = null
) {
    /** Check if the relationship is currently active */
    fun isActive(at: Instant): Boolean {
        if (status != RelationshipStatus.ACTIVE) return false
        val afterStart = validFrom?.let { at >= it } ?: true
        val beforeEnd = validUntil?.let { at <= it } ?: true
        return afterStart && beforeEnd
    }

    /** Check if the relationship has been verified */
    val isVerified: Boolean get() = verifiedAt != null
}

