    @Serializable
    data class Human(
        override val id: String,
        /** Correlation key the engine binds to; UI signals completion against this key. */
        val correlationKey: String,
        /**
         * Bounded wait. The engine makes this the authoritative deadline: the wait activity is
         * scheduled with a start-to-close derived from it. Null does NOT mean "forever" — it
         * hands the bound to the correlation gateway's own default expiry, so an unbounded human
         * step must state the bound it wants here rather than leaving it open.
         */
        val timeoutSeconds: Long? = null,
        /**
         * Payload expression (PayloadExpressionEvaluator.extract syntax) resolving the selected
         * output port name from the signal/form payload — e.g. "$.selectedPort" set by the button
         * the human clicked. Null / no match / non-string result -> SUCCESS_PORT.
         */
        val portExpression: String? = null,
        /**
         * VDX-156: when true (default), every field submitted with the signal/form payload is
         * flat-merged into the `vars` scope (each under [variablePrefix] + '.' + field when a
         * prefix is set, else the bare field name). Routing via [portExpression] is unaffected —
         * it still evaluates against the submitted signal, not `vars`.
         */
        val publishAllSubmittedFields: Boolean = true,
        /** Optional dotted-path prefix for published human fields (VDX-156); null = merge at top level. */
        val variablePrefix: String? = null,
        override val outEdges: Map<String, String> = emptyMap(),
        /**
         * Every output port this step declares (its step-type `outputs` plus the implicit
         * success port), independent of which ports [outEdges] wires. When the envelope
         * fallback names a declared-but-unwired port, the payload is unwrapped and the walk
         * clean-terminates rather than mis-routing to [SUCCESS_PORT]. Empty for hand-built
         * definitions that rely on [outEdges] alone.
         */
        val knownOutputPorts: Set<String> = emptySet(),
    ) : WorkflowTask() {
        init {
            require(timeoutSeconds == null || timeoutSeconds in 1..MAX_HUMAN_TIMEOUT_SECONDS) {
                "Human task '$id' timeoutSeconds must be between 1 and $MAX_HUMAN_TIMEOUT_SECONDS " +
                    "(got $timeoutSeconds)"
            }
        }

        companion object {
            /** One year. An upper bound keeps the engine's derived activity timeout arithmetic total. */
            const val MAX_HUMAN_TIMEOUT_SECONDS: Long = 365L * 24 * 60 * 60
        }
    }

